#!/usr/bin/env python3
"""Genera paper/tables/tab3.tex (tabla principal) y paper/supplement.tex desde los CSV de salida/. Sin números copiados a mano."""
from pathlib import Path

import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
REV, AV, NOV = ROOT / "salida" / "revision", ROOT / "salida" / "avanzado", ROOT / "salida" / "novedoso"
OUT = Path(__file__).resolve().parent
(OUT / "tables").mkdir(exist_ok=True)
NOMBRE = {"P01": "P1", "P02": "P2", "P03": "P3", "P09": "P4"}
OBJ = {"gold_trafico": "Traffic", "gold_ruido": "Noise", "gold_exposicion": "Exposure"}
FEAT = {"fis": "physiology", "fis+mov": "physiology + vibration", "res": "movement-residual physiology",
        "fis+eda": "physiology + EDA", "fis+mov+eda": "physiology + EDA + vibration", "res+eda": "residual physiology + EDA"}


def fp(p):
    return "$<$.001" if p < 0.001 else (f".{int(round(p * 1000)):03d}" if p < 0.01 else f"{p:.2f}".lstrip("0"))


def ses(x):
    return x.replace("sesion_", "legacy ").replace("2026-", "").replace("_", " ")


def f2(x):
    return f"{x:.2f}"


t3 = pd.read_csv(REV / "clasificador_tabla3.csv")
ex = pd.read_csv(REV / "familia_exploratoria_vibracion.csv")
for _, r in ex.iterrows():  # p con 1000 permutaciones para las celdas con vibración
    m = (t3.analisis == r.analisis) & (t3.features == r.features) & (t3.objetivo == r.objetivo)
    t3.loc[m, "p_bloques"] = r.p_bloques_1000
    t3.loc[m, "dagger"] = True

# ---------------- tabla principal
filas = []
for an, titulo in (("A", "A: four participants, no EDA"), ("B", "B: three participants with EDA")):
    filas.append(f"\\multicolumn{{7}}{{l}}{{\\emph{{{titulo}}}}}\\\\")
    for fs in t3[t3.analisis == an].features.unique():
        celdas = []
        for o in OBJ:
            r = t3[(t3.analisis == an) & (t3.features == fs) & (t3.objetivo == o)].iloc[0]
            dag = "$^\\dagger$" if r.get("dagger") is True else ""
            celdas += [f"{r.bal_acc:.2f} [{r.ic_inf:.2f}, {r.ic_sup:.2f}]", fp(r.p_bloques) + dag]
        filas.append(f"~~{FEAT[fs]} & " + " & ".join(celdas) + "\\\\")
    filas.append("\\addlinespace[2pt]")
tab3 = ("\\begin{tabular}{@{}l@{\\hspace{3pt}}c@{\\hspace{2pt}}r@{\\hspace{5pt}}c@{\\hspace{2pt}}r@{\\hspace{5pt}}c@{\\hspace{2pt}}r@{}}\n\\toprule\n"
        "Features & \\multicolumn{2}{c}{Traffic proxy} & \\multicolumn{2}{c}{Noise proxy} & \\multicolumn{2}{c}{Exposure proxy}\\\\\n"
        "\\cmidrule(lr){2-3}\\cmidrule(lr){4-5}\\cmidrule(lr){6-7}\n & BA [95\\,\\% CI] & $p$ & BA [95\\,\\% CI] & $p$ & BA [95\\,\\% CI] & $p$\\\\\n\\midrule\n"
        + "\n".join(filas) + "\n\\bottomrule\n\\end{tabular}\n")
(OUT / "tables" / "tab3.tex").write_text(tab3)

# ---------------- suplemento
S = []
S.append(r"""\documentclass[runningheads]{llncs}
\usepackage[T1]{fontenc}
\usepackage{graphicx,booktabs,array,amsmath,url}
\begin{document}
\title{Supplementary Material: Wearable Sensing in Urban Buses}
\author{Anonymous Authors}\institute{Anonymous Institution}
\renewcommand\thesection{S\arabic{section}}\renewcommand\thetable{S\arabic{table}}\renewcommand\thefigure{S\arabic{figure}}
\maketitle
\noindent This document accompanies the main paper. Every number below is generated by the scripts in the shared code package from the files in \texttt{salida/}. BA = balanced accuracy (chance = 0.33 for three classes); LOPO = leave-one-participant-out; LOSO = leave-one-session-out. Participants are P1--P4; P1 and P4 shared one wristband.
""")

# S1 implementación
S.append(r"""\section{Implementation details}
\begin{table}[h]
\caption{Preprocessing, features, models and statistical settings (all random seeds are 0).}
\footnotesize\centering
\begin{tabular}{@{}>{\raggedright\arraybackslash}p{2.6cm}>{\raggedright\arraybackslash}p{9.1cm}@{}}
\toprule
Component & Setting\\
\midrule
Clock reconstruction & Counter unwrapped with arrival-time prior; sample time $=a+b\,s$ from a robust (two-pass, $3\sigma$) linear fit of arrival time against sample index; nominal rate used if the fitted rate deviates by $>2\,\%$.\\
PPG & Zero-phase Butterworth band-pass, order 3, 0.5--8 Hz for window features and 0.5--4 Hz for beat detection, computed on the window padded by 5 s per side. Idle-pattern samples removed. Beats: peak detection with minimum separation $\max(0.33\,\mathrm{s},\,0.6/f_0)$, prominence 0.3 SD; inter-beat intervals valid if 0.4--1.5 s and within $\pm30\,\%$ of the median; at least 15 valid intervals for HR/SDNN, 10 successive pairs for RMSSD.\\
Spectral HR and quality & Hann window, 4$\times$ zero padding, peak in 0.7--3.0 Hz; quality index = power within $\pm0.2$ Hz of $f_0$ and $\pm0.3$ Hz of $2f_0$ over the 0.5--8 Hz power. A window has valid HR if peak and spectral HR differ by $\le10$ bpm.\\
Coverage thresholds & PPG and ACC $\ge80\,\%$ of expected samples; temperature $\ge50\,\%$; EDA (float packets) $\ge1/3$.\\
Accelerometer & Magnitude of $(x,y,z)$; Welch spectrum, 4-s segments (128 samples at 32 Hz); log band powers 0.3--1, 1--3, 3--6, 6--10, 10--16 Hz and per-axis log SD.\\
Transformations & $\ln$ of RMSSD, SDNN, accelerometer SD and EDA; $z$-score within participant; clipping at $\pm5$ SD. EDA windows start $\ge300$ s after the first EDA packet of the session.\\
Noise & Leq $=10\log_{10}\overline{10^{L/10}}$ over valid seconds; $-120$ dBFS treated as missing.\\
K-Means & $k=2$--6, 10 initialisations. GMM: full covariance, 3 initialisations. Ward linkage. DBSCAN: $\varepsilon\in\{0.8,1.0,1.3,1.6\}$, min.\ samples $\in\{10,20\}$.\\
Random forest & 100 trees, min.\ leaf size 5, balanced class weights. Logistic regression: L2, $C=1$, balanced weights, 2000 iterations.\\
Mixed models & statsmodels \texttt{MixedLM}, REML, random intercept per session, non-overlapping windows (every second window of each bus segment).\\
Uncertainty & 95\,\% CIs from 2000 bootstrap resamples of whole sessions. Permutation tests: labels shifted circularly within each (session, bus-segment) block (preserves autocorrelation); 200 permutations for classifier cells, 1000 for the vibration cells, 2000 for H2, 500 for H1 (noise series shifted within session), 2000 for cluster NMI.\\
Multiple tests & Holm--Bonferroni. Family 1 (confirmatory): H1, H2 and the six physiology-only classifier cells. Family 2 (exploratory): the three vibration cells.\\
Software & Python 3.13.9, NumPy 2.3.5, pandas 2.3.3, SciPy 1.16.3, scikit-learn 1.7.2, statsmodels 0.14.5, matplotlib 3.10.6, pyarrow 21.0.0.\\
\bottomrule
\end{tabular}
\end{table}
""")

# S2 clasificador completo + holm
full = t3.copy()
rows = []
for _, r in full.iterrows():
    rows.append(f"{r.analisis} & {FEAT[r.features]} & {OBJ[r.objetivo]} & {int(r.n)} & {r.bal_acc:.3f} & [{r.ic_inf:.3f}, {r.ic_sup:.3f}] & {r.f1_macro:.3f} & {r.nulo_media:.3f} & {r.nulo_p95:.3f} & {fp(r.p_bloques)} & " + ("--" if pd.isna(r.get('p_holm')) else fp(r.p_holm)) + "\\\\")
S.append("\\section{Cross-person classifiers: full results}\n\\begin{table}[h]\n\\caption{Random forest, LOPO. Null = block-permutation distribution of BA. Holm-adjusted $p$ is given for the confirmatory family (with H1 and H2); $p$ of the three vibration cells uses 1000 permutations, the rest 200.}\n\\tiny\\centering\n\\begin{tabular}{@{}llllrccccrr@{}}\n\\toprule\nAn. & Features & Target & $n$ & BA & 95\\,\\% CI & F1 & Null mean & Null p95 & $p$ & $p_\\mathrm{Holm}$\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")
fam = pd.read_csv(REV / "familia_confirmatoria_holm.csv")
fam2 = pd.read_csv(REV / "familia_exploratoria_vibracion.csv")
S.append("\\begin{table}[h]\n\\caption{Multiple-comparison control. Family 1: H1 primary, H2 and the six physiology-only classifier cells. Family 2 (exploratory): vibration cells.}\n\\small\\centering\n\\begin{tabular}{@{}lrr@{}}\n\\toprule\nTest & raw $p$ & Holm $p$\\\\\n\\midrule\n" + "\n".join(f"{r.prueba.replace('gold_', '').replace('_', ' ')} & {fp(r.p_cruda)} & {fp(r.p_holm)}\\\\" for _, r in fam.iterrows())
         + "\n\\midrule\n" + "\n".join(f"{r.analisis}: {FEAT[r.features]}, {OBJ[r.objetivo].lower()} & {fp(r.p_bloques_1000)} & {fp(r.p_holm_fam2)}\\\\" for _, r in fam2.iterrows()) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")

# S3 por participante y por sesión
pp = pd.read_csv(REV / "bal_acc_por_participante.csv")
pp = pp[pp.features.isin(["fis", "fis+mov", "fis+eda", "fis+mov+eda"]) & pp.objetivo.isin(["gold_trafico", "gold_ruido"])]
pv = pp.pivot_table(index=["analisis", "features", "objetivo"], columns="participante", values="bal_acc").round(2)
rows = [f"{a} & {FEAT[f]} & {OBJ[o]} & " + " & ".join("--" if pd.isna(pv.loc[(a, f, o)].get(p)) else f"{pv.loc[(a, f, o)][p]:.2f}" for p in ["P01", "P02", "P03", "P09"]) + "\\\\" for (a, f, o) in pv.index]
S.append("\\section{Breakdown by participant and session}\n\\begin{table}[h]\n\\caption{BA of the held-out participant (LOPO folds). ``--'' = participant not in the analysis.}\n\\footnotesize\\centering\n\\begin{tabular}{@{}lllcccc@{}}\n\\toprule\nAn. & Features & Target & P1 & P2 & P3 & P4\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")
ps = pd.read_csv(REV / "bal_acc_por_sesion.csv")
ps = ps[(ps.analisis == "A") & ps.features.isin(["fis", "fis+mov"]) & (ps.objetivo == "gold_trafico")]
pv = ps.pivot_table(index="sesion", columns="features", values="bal_acc").round(2)
nn = ps.groupby("sesion").n.first()
rows = [f"{ses(s)} & {int(nn[s])} & {pv.loc[s, 'fis']:.2f} & {pv.loc[s, 'fis+mov']:.2f}\\\\" for s in pv.index]
S.append("\\begin{table}[h]\n\\caption{Analysis A, traffic proxy: BA in each session (pooled LOPO predictions of that session's windows).}\n\\footnotesize\\centering\n\\begin{tabular}{@{}lrcc@{}}\n\\toprule\nSession & $n$ & physiology & + vibration\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")

# S4 matrices de confusión
cm = pd.read_csv(REV / "matrices_confusion.csv")
S.append("\\section{Confusion matrices}\n")
for fs in ("fis", "fis+mov"):
    c = cm[(cm.analisis == "A") & (cm.features == fs) & (cm.objetivo == "gold_trafico")]
    cls = [x for x in c.columns if x not in ("real", "analisis", "features", "objetivo")]
    rows = [f"{r.real} & " + " & ".join(f"{r[k]:.2f}" for k in cls) + "\\\\" for _, r in c.iterrows()]
    S.append(f"\\begin{{table}}[h]\n\\caption{{Analysis A, traffic proxy, {FEAT[fs]}: row-normalised confusion matrix (rows = true class, columns = predicted).}}\n\\footnotesize\\centering\n\\begin{{tabular}}{{@{{}}l" + "c" * len(cls) + "@{}}\n\\toprule\n & " + " & ".join(cls) + "\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")
h2c = pd.read_csv(REV / "h2_matriz_confusion.csv", index_col=0).values
S.append(f"\\begin{{table}}[h]\n\\caption{{H2, LOPO logistic regression at threshold 0.5 (counts). Error rate 23.2\\,\\%; misses of stopped windows 26.9\\,\\%, false alarms 20.0\\,\\%.}}\n\\footnotesize\\centering\n\\begin{{tabular}}{{@{{}}lcc@{{}}}}\n\\toprule\n & predicted moving & predicted stopped\\\\\n\\midrule\ntrue moving & {h2c[0, 0]} & {h2c[0, 1]}\\\\\ntrue stopped & {h2c[1, 0]} & {h2c[1, 1]}\\\\\n\\bottomrule\n\\end{{tabular}}\n\\end{{table}}\n")

# S5 H2: ablación, errores, sensibilidad
ab = pd.read_csv(REV / "h2_ablacion.csv")
rows = [f"{r.grupo} & {r.auc_solo:.3f} & " + ("--" if pd.isna(r.auc_sin) else f"{r.auc_sin:.3f}") + "\\\\" for _, r in ab.iterrows()]
S.append("\\section{H2: accelerometer detector}\n\\begin{table}[h]\n\\caption{Feature-group ablation (LOPO AUC, logistic regression): group alone, and all features except the group.}\n\\footnotesize\\centering\n\\begin{tabular}{@{}lcc@{}}\n\\toprule\nGroup & AUC alone & AUC without\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")
e1, e2, e3 = (pd.read_csv(REV / f) for f in ("h2_error_por_frac_detenido.csv", "h2_error_por_gps.csv", "h2_error_por_sesion.csv"))
r1 = [f"{r.bin_det} & {int(r.n)} & {r.tasa_error * 100:.1f}\\\\" for _, r in e1.iterrows()]
r2 = [f"{r.bin_gps} & {int(r.n)} & {r.tasa_error * 100:.1f}\\\\" for _, r in e2.iterrows()]
S.append("\\begin{table}[h]\n\\caption{H2 error analysis. Error rate by fraction of the window spent stopped (GPS), by GPS accuracy, and in the four worst sessions.}\n\\footnotesize\\centering\n\\begin{tabular}{@{}lrr@{}}\n\\toprule\nStopped fraction & $n$ & error (\\%)\\\\\n\\midrule\n" + "\n".join(r1) + "\n\\midrule\nGPS accuracy & $n$ & error (\\%)\\\\\n\\midrule\n" + "\n".join(r2) + "\n\\midrule\nSession (worst four) & $n$ & error (\\%) / AUC\\\\\n\\midrule\n"
         + "\n".join(f"{ses(r.sesion)} & {int(r.n)} & {r.tasa_error * 100:.1f} / " + ("--" if pd.isna(r.auc) else f"{r.auc:.2f}") + "\\\\" for _, r in e3.head(4).iterrows()) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")
S.append(r"""\noindent \textbf{Sensitivity to label selection and to wristband.} Restricting H2 to windows whose \emph{bus} label was used as recorded (P2 sessions 1--3, P3, P4; $n=358$) gives LOPO AUC 0.876. AUC by wristband (LOPO predictions): wristband A (P1, P4) 0.81; B (P2) 0.83; C (P3) 0.91. \textbf{Speed regression (exploratory).} Random forest regression of mean GPS speed from the same features, LOPO: Spearman 0.49, $R^2=0.12$, MAE 6.9 km/h (8.5 km/h for the mean predictor); per participant Spearman 0.61, 0.41, 0.61, 0.73 (P1--P4).
""")

# S6 mixed models
mm = pd.read_csv(REV / "mixto_icc_mde.csv")
mm0 = pd.read_csv(AV / "modelo_mixto.csv")
mm = mm.merge(mm0[["resultado", "termino", "ic_inf", "ic_sup", "p"]], on=["resultado", "termino"], how="left")
mm = mm[mm.resultado != "hr_res"].drop_duplicates(["resultado", "termino"])
nm = {"hr_picos_bpm": "HR (bpm)", "lnrmssd": "ln RMSSD", "temp_media_c": "skin temp. ($^\\circ$C)", "ln_eda": "ln EDA"}
tn = {"ruido_z": "noise (per SD)", "cong_z": "congestion (per SD)", "acc_z": "movement (per SD)", "hora_z": "hour (per SD)"}
rows = [f"{nm[r.resultado]} & {tn[r.termino]} & {r.coef:.3f} & [{r.ic_inf:.3f}, {r.ic_sup:.3f}] & {fp(r.p)} & {r.mde_80:.3f} & {r.icc_sesion:.2f}\\\\" for _, r in mm.iterrows()]
S.append("\\section{Mixed models}\n\\begin{table}[h]\n\\caption{Fixed effects, 95\\,\\% CI, approximate minimum detectable effect (80\\,\\% power, $2.8\\,$SE) and session intraclass correlation. $n=318$ non-overlapping windows from 11 sessions (EDA: $n=200$).}\n\\tiny\\centering\n\\begin{tabular}{@{}llrcrrr@{}}\n\\toprule\nOutcome & Predictor & Coef. & 95\\,\\% CI & $p$ & MDE & ICC\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")

# S7 Bayes
by = pd.read_csv(REV / "h1_bayes_poder.csv")
rows = [f"{r.analisis} & {r.estimado:+.2f} & {r.se:.2f} & {r.mde_80:.1f} & {r.prior_sd:.0f} & {r.BF01:.2f} & {r.post_media:+.2f} [{r.post_ic_inf:+.2f}, {r.post_ic_sup:+.2f}]\\\\" for _, r in by.iterrows()]
S.append("\\section{H1: power and Bayesian analysis}\n\\begin{table}[h]\n\\caption{Normal approximation to the contrast (SE from the bootstrap CI), zero-centred normal prior on the effect. $\\mathrm{BF}_{01}>1$ favours no effect; values near 1 are uninformative.}\n\\footnotesize\\centering\n\\begin{tabular}{@{}lrrrrrl@{}}\n\\toprule\nAnalysis & $\\Delta$HR & SE & MDE & prior SD & BF$_{01}$ & posterior mean [95\\,\\% CrI]\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")

# S7b variantes H1 (parseadas del log de sensibilidad)
import re
txt = (NOV / "h1_sens_log.txt").read_text()
nom = ["$\\geq$6 dB, top 10\\,\\% (primary)", "$\\geq$4 dB, top 20\\,\\%", "$\\geq$3 dB, top 30\\,\\%"]
hh = re.findall(r"eventos=(\d+) en (\d+) sesiones .*?= ([+-][\d.]+) lpm\s+IC95%\(sesiones\)=\[([+-][\d.]+), ([+-][\d.]+)\]\s+p\(permutación\)=([\d.]+)", txt)
rows = [f"{nom[i]} & {e} & {s_} & {d} & [{lo}, {hi}] & {float(p):.2f}\\\\" for i, (e, s_, d, lo, hi, p) in enumerate(hh)]
S.append("\\begin{table}[h]\n\\caption{H1: event-locked HR contrast (events minus controls) for the pre-specified burst definition and two looser sensitivity definitions. $p$ from circular shifts of the noise series within session.}\n\\footnotesize\\centering\n\\begin{tabular}{@{}lrrcrr@{}}\n\\toprule\nBurst definition & Events & Sessions & $\\Delta$HR (bpm) & 95\\,\\% CI & $p$\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")

# S8 correlaciones
co = pd.read_csv(REV / "correlacion_features.csv", index_col=0)
rows = [f"{i} & " + " & ".join(f"{v:.2f}" for v in co.loc[i]) + "\\\\" for i in co.index]
S.append("\\section{Feature redundancy and proxy--vibration coupling}\n\\begin{table}[h]\n\\caption{Spearman correlation between window features (analysis A, $n=1267$).}\n\\footnotesize\\centering\n\\begin{tabular}{@{}l" + "c" * len(co) + "@{}}\n\\toprule\n & " + " & ".join(co.columns) + "\\\\\n\\midrule\n" + "\n".join(rows) + "\n\\bottomrule\n\\end{tabular}\n\\end{table}\n")
S.append("\\noindent The traffic proxy (fraction of time stopped) and the vibration feature (ln SD of acceleration magnitude) are strongly anti-correlated: Spearman $-0.54$ over all windows with speed ($n=1054$), and $-0.47$, $-0.57$, $-0.61$, $-0.77$ within P1--P4. Models given vibration therefore see the proxy's own physical cause.\n")
S.append("\\section{Decoded signals}\n\\begin{figure}[h]\n\\centering\n\\includegraphics[width=\\textwidth]{figs/fig2_signals.pdf}\n\\caption{Decoded channels from one session: (a) PPG with detected beats, (b) accelerometer magnitude close to 1~g (dashed), (c) skin temperature, (d) EDA from float packets.}\n\\end{figure}\n")
S.append("\\end{document}\n")
(OUT / "supplement.tex").write_text("\n".join(S))
print("tablas generadas:", sorted(p.name for p in (OUT / "tables").iterdir()), "| supplement.tex", len("\n".join(S)), "caracteres")
